pub(super) fn block_menu_icons(theme: Theme) -> BlockMenuIcons {
    let fill = theme.text_secondary;
    BlockMenuIcons {
        add: block_menu_icon(ADD_PATHS, theme.text_muted),
        handle: block_menu_icon(HANDLE_PATHS, theme.text_muted),
        turn_into: block_menu_icon(TURN_INTO_PATHS, fill),
        color: block_menu_icon(COLOR_PATHS, fill),
        quote_size: block_menu_icon(QUOTE_SIZE_PATHS, fill),
        code_language: block_menu_icon(CODE_LANGUAGE_PATHS, fill),
        code_wrap: block_menu_icon(CODE_WRAP_PATHS, fill),
        copy_code: block_menu_icon(COPY_CODE_PATHS, fill),
        code_action_copy: small_block_menu_icon(CODE_ACTION_COPY_PATHS, fill),
        code_action_language_chevron: small_block_menu_icon(
            CODE_ACTION_LANGUAGE_CHEVRON_PATHS,
            fill,
        ),
        copy_link: block_menu_icon(COPY_LINK_PATHS, fill),
        duplicate: block_menu_icon(DUPLICATE_PATHS, fill),
        move_to: block_menu_icon(MOVE_TO_PATHS, fill),
        delete: block_menu_icon(DELETE_PATHS, fill),
        comment: block_menu_icon(COMMENT_PATHS, fill),
        suggest_edits: block_menu_icon(SUGGEST_EDITS_PATHS, fill),
        present: block_menu_icon(PRESENT_PATHS, fill),
        ask_ai: block_menu_icon(ASK_AI_PATHS, fill),
        skills: block_menu_icon(SKILLS_PATHS, fill),
        chevron: small_block_menu_icon(CHEVRON_PATHS, theme.text_muted),
    }
}

fn block_menu_icon(paths: &[&str], fill: u32) -> IconAsset {
    IconAsset::new(svg_with_paths("0 0 20 20", paths, fill))
}

fn small_block_menu_icon(paths: &[&str], fill: u32) -> IconAsset {
    IconAsset::new(svg_with_paths("0 0 16 16", paths, fill))
}
